# -*- coding: utf-8 -*-
import os
_PRIV_REPOS = os.environ.get("PW1K_PRIVATE_REPOS", "") or "(?!x)x"   # |-separated names of your private repositories
_PRIV_HOSTS = os.environ.get("PW1K_PRIVATE_HOSTS", "") or "(?!x)x"   # |-separated names of your machines
"""Rule tables for pw1k.py (author an agent, 12 Nov 2026): GLOSS, RX, FN, EVENTS.

Ids P0001.. follow the load order TERMS, MATH (pw1k_terms.py), then GLOSS, RX, FN, EVENTS here.
Append only: ids follow the order. A rule that must go is replaced by a rule on the same subject, never deleted.

Scopes of an RX rule (first field, optional minimum count after the letter):
  lower case = detexed prose, case-insensitive: p body, a abstract, t title, s statements, f proofs, c captions,
               i first section, h headings.  In prose a formula is \x01, a numeric cite \x02, a textual cite \x05,
               a cross-reference \x03.
  upper case = raw text, case-sensitive: M formulas, R body, A abstract, T title, S statements, B bibliography,
               W whole file, E preamble.
Dated remarks in the texts are the owner's, from his prompts of 2026.
"""

_NC = r"(?![^.]{0,200}[\x02\x05])"          # no citation later in the sentence
_NR = r"(?![^.,;]{0,80}\x03)"               # no cross-reference close by
_NN = r"(?![^.]{0,140}(?:\x01|\d))"         # no number or formula later in the sentence
_SB = r"(?:[.!?]\s+|\n[ \t]*\n[ \t]*)"            # sentence break
_PFX = r"(?:thm|theorem|lem|lemma|prop|proposition|cor|corollary|def|defn|definition|rem|rmk|remark|eq|eqn|sec|subsec|" \
       r"fig|tab|app|alg|ass|conj|claim|ex)"

